Given a head of linked list where each node has two links: next pointer pointing to the next node and random pointer to any random node in the list. Create a clone of this linked list. Table of Content[Naive Approach] Using Hashing - O(n) Time and O(n) Space[Expected Approach] By Inserting Nodes In-place - O(n) Time and O(1) Space[Naive Approach] Using Hashing - O(n) Time and O(n) SpaceThe idea is to create a new node for each original node, store them in a hash table, then update the next and random pointers of the new nodes.Try It YourselfCreate a hash table mp to map original nodes to new nodes.  Traverse the original list and for each node curr, create a new node and store it in the hash table mp[curr] = new Node().  Traverse the list again to update the next and random pointers of the new nodes: mp[curr]->next = mp[curr->next] and mp[curr]->random = mp[curr->random].  Return mp[head] as the head of the cloned linked list.
            C++

    #include <iostream>
#include <unordered_map>
using namespace std;

class Node {
public:

    int data;
    Node* next;
    Node* random;

    Node(int x) {
        data = x;
        next = random = NULL;
    }
};

Node* cloneLinkedList(Node* head) {

    unordered_map<Node*, Node*> mp;
    Node *curr = head;

    // Traverse original linked list to store new 
  	// nodes corresponding to original linked list
    while (curr != NULL) {
        mp[curr] = new Node(curr->data);
        curr = curr->next;
    }

  	curr = head;

    // Loop to update the next and random pointers 
  	// of new nodes 
    while (curr != NULL) {

      	mp[curr]->next = mp[curr->next];

      	mp[curr]->random = mp[curr->random];

      	curr = curr->next;
    }

    return mp[head];
}

void printList(Node* head) {
    while (head != NULL) {
        cout << head->data << "(";
      	if(head->random)
          	cout << head->random->data << ")";
      	else 
          	cout << "null" << ")";

      	if(head->next != NULL)
          	cout << " -> ";
        head = head->next;
    }
    cout << endl;
}

int main() {

    // Creating a linked list with random pointer
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    head->next->next->next = new Node(4);
    head->next->next->next->next = new Node(5);
    head->random = head->next->next;
    head->next->random = head;
    head->next->next->random = head->next->next->next->next;
    head->next->next->next->random = head->next->next;
    head->next->next->next->next->random = head->next;

    // Print the original list
    cout << "Original linked list:\n";
    printList(head);

    Node* clonedList = cloneLinkedList(head);

    cout << "Cloned linked list:\n";
    printList(clonedList);

    return 0;
}


